sys_script.script:
(function executeRule(current, previous) {

    // =====================================================
    // Find the active Staff Shift for a user
    // =====================================================
    function getActiveStaffShift(userSysId) {

        if (!userSysId) {
            return null;
        }

        var shift = new GlideRecord('x_snc_flowops_staff_shift');

        shift.addQuery('staff', userSysId);
        shift.addQuery('shift_status', 'active');
        shift.setLimit(1);
        shift.query();

        if (shift.next()) {
            return shift;
        }

        return null;
    }


    // =====================================================
    // 1. NEW WORK ORDER
    // =====================================================

    if (current.operation() == 'insert') {

        if (current.assigned_engineer) {

            var newShift = getActiveStaffShift(
                current.assigned_engineer.toString()
            );

            if (newShift) {

                var count = parseInt(
                    newShift.assigned_room_count,
                    10
                ) || 0;

                newShift.assigned_room_count = count + 1;
                newShift.update();
            }
        }

        return;
    }


    // =====================================================
    // 2. WORK ORDER STATUS CHANGE
    // =====================================================
	if (current.status.changes()) {

		var oldStatus = previous.getValue('status');
		var newStatus = current.getValue('status');

		// Resolved or Escalated means the workload is finished
		var isFinished =
			newStatus == 'resolved' ||
			newStatus == 'escalate';

		// Previously active workload
		var wasActive =
			oldStatus != 'resolved' &&
			oldStatus != 'escalate';

		if (
			isFinished &&
			wasActive &&
			current.assigned_engineer
		) {

			var completedShift = getActiveStaffShift(
				current.assigned_engineer.toString()
			);

			if (completedShift) {

				var currentCount = parseInt(
					completedShift.getValue('assigned_room_count'),
					10
				) || 0;

				completedShift.setValue(
					'assigned_room_count',
					Math.max(0, currentCount - 1)
				);

				completedShift.update();
			}
		}
	}
    // =====================================================
    // 3. HANDLE REASSIGNMENT
    // =====================================================

    if (current.assigned_engineer.changes()) {

        /*
         * Remove workload from previous engineer
         */

        if (
            previous.assigned_engineer &&
            previous.getDisplayValue('status') != 'Completed'
        ) {

            var oldShift = getActiveStaffShift(
                previous.assigned_engineer.toString()
            );

            if (oldShift) {

                var oldCount = parseInt(
                    oldShift.assigned_room_count,
                    10
                ) || 0;

                oldShift.assigned_room_count =
                    Math.max(0, oldCount - 1);

                oldShift.update();
            }
        }


        /*
         * Add workload to new engineer
         */

        if (
            current.assigned_engineer &&
            current.getDisplayValue('status') != 'Completed'
        ) {

            var newAssignedShift = getActiveStaffShift(
                current.assigned_engineer.toString()
            );

            if (newAssignedShift) {

                var newAssignedCount = parseInt(
                    newAssignedShift.assigned_room_count,
                    10
                ) || 0;

                newAssignedShift.assigned_room_count =
                    newAssignedCount + 1;

                newAssignedShift.update();
            }
        }
    }

})(current, previous);
